css:
.center-box {
  display: grid;
  place-items: center;
  min-height: 180px;
  border: 1px dashed #a4f06a;
  border-radius: 12px;
  color: #a4f06a;
}

.flex-box {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 180px;
  border: 1px dashed #a4f06a;
}

.grid-demo {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px;
}
.grid-demo span { padding: 24px; background: #24344a; border-radius: 10px; }

.sticky-demo {
  position: sticky;
  top: 0;
  z-index: 10;
  padding: 18px;
  background: #18243a;
  border-bottom: 2px solid #a4f06a;
}

.ratio-box {
  aspect-ratio: 16 / 9;
  display: grid;
  place-items: center;
  max-width: 360px;
  background: #24344a;
  border-radius: 12px;
}

.fluid-title {
  font-size: clamp(2rem, 7vw, 5rem);
  line-height: 1.05;
  letter-spacing: -0.06em;
}

.gradient-type {
  background: linear-gradient(90deg, #a4f06a, #73d9df, #a78bfa);
  color: transparent;
  background-clip: text;
  -webkit-background-clip: text;
}

.shadow-type {
  color: #f4f7fb;
  text-shadow: 0 2px 0 #61708a, 0 8px 24px #73d9df66;
}

.underline-link {
  color: #f4f7fb;
  text-decoration: none;
  background: linear-gradient(#a4f06a, #a4f06a) left bottom / 0 2px no-repeat;
  transition: background-size .25s ease;
  padding-bottom: 5px;
}
.underline-link:hover { background-size: 100% 2px; }

.selection-demo::selection {
  color: #10170c;
  background: #a4f06a;
}

.glass-wrap { padding: 35px; background: linear-gradient(120deg, #253c62, #6b3975); border-radius: 14px; }
.glass-card {
  padding: 25px;
  color: white;
  background: #ffffff20;
  border: 1px solid #ffffff55;
  border-radius: 12px;
  backdrop-filter: blur(12px);
}

.soft-card {
  padding: 30px;
  border-radius: 18px;
  background: #18243a;
  box-shadow: 10px 10px 24px #080d16, -8px -8px 22px #263751;
}

.gradient-border {
  padding: 2px;
  border-radius: 14px;
  background: linear-gradient(120deg, #a4f06a, #73d9df);
}
.gradient-border > div { padding: 24px; border-radius: 12px; background: #101827; }

.glow-button {
  padding: 13px 22px;
  color: #a4f06a;
  background: #172316;
  border: 1px solid #a4f06a;
  border-radius: 9px;
  box-shadow: 0 0 8px #a4f06a66, 0 0 24px #a4f06a33;
}

.image-overlay {
  min-height: 150px;
  display: flex;
  align-items: end;
  padding: 20px;
  border-radius: 12px;
  background: linear-gradient(0deg, #090b10, transparent), linear-gradient(120deg, #315a55, #273b68);
  color: white; font-weight: 800;
}

.lift-card {
  padding: 28px;
  border: 1px solid #42516a;
  border-radius: 12px;
  background: #18243a;
  transition: transform .2s ease, box-shadow .2s ease;
}
.lift-card:hover { transform: translateY(-7px); box-shadow: 0 14px 28px #0005; }

.press-button {
  padding: 13px 20px; border: 0; border-radius: 9px;
  background: #a4f06a; color: #10170c; font-weight: 800;
  box-shadow: 0 5px 0 #5e9a36; transition: transform .1s, box-shadow .1s;
}
.press-button:active { transform: translateY(4px); box-shadow: 0 1px 0 #5e9a36; }

html { scroll-behavior: smooth; }
.scroll-demo { height: 170px; overflow: auto; padding: 15px; background: #18243a; border-radius: 10px; }
.scroll-space { height: 100px; }

.tip { position: relative; padding: 12px 16px; border: 1px solid #52647c; border-radius: 8px; background: #18243a; color: white; }
.tip::after { content: attr(data-tip); position: absolute; left: 50%; bottom: calc(100% + 10px); transform: translate(-50%, 4px); padding: 7px 9px; border-radius: 6px; background: #a4f06a; color: #10170c; font-size: 11px; white-space: nowrap; opacity: 0; pointer-events: none; transition: .2s; }
.tip:hover::after, .tip:focus-visible::after { opacity: 1; transform: translate(-50%, 0); }

.skeleton-card { width: 180px; padding: 14px; background: #18243a; border-radius: 10px; }
.skeleton-card div,.skeleton-card span { display: block; border-radius: 6px; background: linear-gradient(90deg,#26364c 25%,#40536b 50%,#26364c 75%); background-size: 200% 100%; animation: shimmer 1.4s infinite; }
.skeleton-card div { height: 55px; margin-bottom: 12px; } .skeleton-card span { height: 8px; margin-top: 7px; width: 80%; }
@keyframes shimmer { to { background-position: -200% 0; } }

.motion-card { padding: 22px; background: #18243a; border-radius: 10px; animation: arrive .5s ease both; }
@keyframes arrive { from { opacity: 0; transform: translateY(12px); } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; } }

.scrollbox { height: 125px; overflow: auto; padding: 14px; background: #18243a; border-radius: 9px; color: #cbd5e1; font-size: 12px; }
.scrollbox::-webkit-scrollbar { width: 8px; }
.scrollbox::-webkit-scrollbar-track { background: #101827; }
.scrollbox::-webkit-scrollbar-thumb { background: #627b5a; border-radius: 9px; }

.container-demo { container-type: inline-size; resize: horizontal; overflow: auto; width: 100%; max-width: 340px; padding: 10px; border: 1px dashed #52647c; }
.container-card { padding: 16px; background: #18243a; border-radius: 8px; }
@container (min-width: 260px) { .container-card { background: #243d2c; color: #caffaa; } }

.page-shell { min-height: 190px; display: flex; flex-direction: column; padding: 12px; background: #18243a; border-radius: 10px; }
.page-shell header,.page-shell footer { padding: 10px; background: #26364c; }
.page-shell main { flex: 1; padding: 12px; }

.ticker { width: 100%; overflow: hidden; color: #a4f06a; white-space: nowrap; font-weight: 800; }
.ticker div { display: inline-block; animation: ticker 9s linear infinite; }
.ticker:hover div { animation-play-state: paused; }
@keyframes ticker { to { transform: translateX(-35%); } }

.steps { list-style: none; counter-reset: step; padding: 0; color: #eaf0f8; }
.steps li { counter-increment: step; margin: 8px 0; }
.steps li::before { content: counter(step, decimal-leading-zero); color: #a4f06a; font: 11px 'monospace'; margin-right: 12px; }

.has-card { display: flex; gap: 10px; align-items: center; padding: 20px; border: 1px solid #52647c; border-radius: 10px; color: #eaf0f8; }
.has-card:has(input:checked) { border-color: #a4f06a; background: #a4f06a12; }
.has-card input { accent-color: #a4f06a; }

